CREATE TYPE "writing_submission_status" AS ENUM ('DRAFT', 'SUBMITTED', 'EVALUATED', 'FAILED');
CREATE TYPE "speaking_session_status" AS ENUM ('IN_PROGRESS', 'COMPLETED', 'FAILED');
CREATE TABLE "writing_submissions" ("id" uuid PRIMARY KEY, "user_id" uuid REFERENCES "users"("id"), "guest_id" uuid, "exam_type" exam_type, "task_type" varchar(64) NOT NULL, "prompt" jsonb NOT NULL, "text" text NOT NULL, "status" writing_submission_status NOT NULL DEFAULT 'DRAFT', "created_at" timestamptz NOT NULL DEFAULT now(), "submitted_at" timestamptz);
CREATE TABLE "writing_feedback" ("id" uuid PRIMARY KEY, "submission_id" uuid NOT NULL UNIQUE REFERENCES "writing_submissions"("id") ON DELETE CASCADE, "provider" varchar(128) NOT NULL, "model" varchar(128), "content" jsonb NOT NULL, "created_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "speaking_sessions" ("id" uuid PRIMARY KEY, "user_id" uuid REFERENCES "users"("id"), "guest_id" uuid, "exam_type" exam_type, "status" speaking_session_status NOT NULL DEFAULT 'IN_PROGRESS', "created_at" timestamptz NOT NULL DEFAULT now(), "completed_at" timestamptz);
CREATE TABLE "speaking_turns" ("id" uuid PRIMARY KEY, "session_id" uuid NOT NULL REFERENCES "speaking_sessions"("id") ON DELETE CASCADE, "turn_order" integer NOT NULL, "prompt" text, "transcript" text, "audio_media_id" uuid, "feedback" jsonb, "created_at" timestamptz NOT NULL DEFAULT now(), CONSTRAINT "speaking_turns_session_order_idx" UNIQUE("session_id", "turn_order"));
